{ "explanation": "The 68-95-99.7 rule (empirical rule) says that for a normal distribution, about 68% of values lie within 1 standard deviation of the mean, 95% within 2, and 99.7% within 3. The visualization shows the standard normal curve with the ±1σ, ±2σ, and ±3σ regions shaded in layers, labeled with their percentages. Drag the orange dot along the axis (or use the buttons) to shade P(μ−kσ ≤ X ≤ μ+kσ) for any k and see the exact probability — notice it hits 68.27%, 95.45%, and 99.73% at k = 1, 2, 3.", "manimCode": "// ---------- Title ----------
const title = new Text({ text: 'The 68-95-99.7 Rule', color: WHITE, fontSize: 36 });
title.moveTo([-0.6, 3.5, 0]);
const subtitle = new Text({ text: '(Empirical Rule) for a normal distribution', color: GRAY, fontSize: 20 });
subtitle.moveTo([-0.6, 3.08, 0]);
await scene.play(new Write(title));
await scene.play(new FadeIn(subtitle));

// ---------- Axes & bell curve ----------
const ax = new Axes({ xRange: [-4, 4, 1], yRange: [0, 0.5, 0.1], xLength: 10, yLength: 4.4, tips: false });
ax.moveTo([0, -0.7, 0]);
const pdf = function (x) { return Math.exp(-x * x / 2) / Math.sqrt(2 * Math.PI); };
const curve = ax.plot(pdf, { color: WHITE, xRange: [-3.8, 3.8], numSamples: 200 });
curve.setStrokeWidth(3);
await scene.play(new FadeIn(ax));
await scene.play(new Create(curve));

// ---------- Shaded bands: 3σ, 2σ, 1σ ----------
const area3 = ax.getArea(curve, [-3, 3], { color: BLUE_E, opacity: 0.30 });
const area2 = ax.getArea(curve, [-2, 2], { color: BLUE_D, opacity: 0.40 });
const area1 = ax.getArea(curve, [-1, 1], { color: BLUE_C, opacity: 0.55 });
await scene.play(new FadeIn(area3));
await scene.play(new FadeIn(area2));
await scene.play(new FadeIn(area1));

// ---------- σ tick labels under the axis ----------
const sigmaNames = ['μ-3σ', 'μ-2σ', 'μ-σ', 'μ', 'μ+σ', 'μ+2σ', 'μ+3σ'];
const sigmaLabels = [];
for (let i = -3; i <= 3; i++) {
  const s = new Text({ text: sigmaNames[i + 3], color: WHITE, fontSize: 18 });
  const p = ax.c2p(i, 0);
  s.moveTo([p[0], p[1] - 0.38, 0]);
  sigmaLabels.push(s);
}
await scene.play(new FadeIn(new VGroup(...sigmaLabels)));

// ---------- Separator lines at ±1σ, ±2σ, ±3σ ----------
const sepLines = [];
for (const i of [-3, -2, -1, 1, 2, 3]) {
  const ln = new Line({ start: ax.c2p(i, 0), end: ax.c2p(i, pdf(i)), color: WHITE });
  ln.setStrokeWidth(1.5);
  ln.setOpacity(0.35);
  sepLines.push(ln);
}
await scene.play(new FadeIn(new VGroup(...sepLines)));

// ---------- Percentage labels ----------
const lbl68 = new Text({ text: '68%', color: WHITE, fontSize: 30 });
lbl68.moveTo(ax.c2p(0, 0.12));
const lbl95 = new Text({ text: '95%', color: WHITE, fontSize: 24 });
lbl95.moveTo(ax.c2p(0, 0.235));
const lbl997 = new Text({ text: '99.7%', color: WHITE, fontSize: 20 });
lbl997.moveTo(ax.c2p(0, 0.33));
await scene.play(new AnimationGroup([new FadeIn(lbl68), new FadeIn(lbl95), new FadeIn(lbl997)]));

// ---------- Probability readout ----------
const formula = new Text({ text: 'P(μ-kσ ≤ X ≤ μ+kσ) =', color: WHITE, fontSize: 24 });
formula.moveTo([-2.6, 2.55, 0]);
await scene.play(new Write(formula));

let k = 1;
let pctText = new Text({ text: '68.27%', color: ORANGE, fontSize: 30 });
pctText.moveTo([1.45, 2.55, 0]);
let kText = new Text({ text: 'k = 1.00', color: WHITE, fontSize: 20 });
kText.moveTo([1.45, 2.12, 0]);
await scene.play(new AnimationGroup([new FadeIn(pctText), new FadeIn(kText)]));

// ---------- Interactive probe region (±kσ) ----------
let probeArea = ax.getArea(curve, [-1, 1], { color: ORANGE, opacity: 0.45 });
const segL = new Polygon({ vertices: [ax.c2p(-1, 0), ax.c2p(-1, pdf(1))], color: ORANGE });
segL.setStrokeWidth(3).setFillOpacity(0);
const segR = new Polygon({ vertices: [ax.c2p(1, 0), ax.c2p(1, pdf(1))], color: ORANGE });
segR.setStrokeWidth(3).setFillOpacity(0);
const dotK = new Dot({ point: ax.c2p(1, 0), color: ORANGE });
await scene.play(new AnimationGroup([new FadeIn(probeArea), new FadeIn(segL), new FadeIn(segR), new FadeIn(dotK)]));

const hint = new Text({ text: 'drag me!', color: YELLOW, fontSize: 18 });
hint.moveTo([2.95, -2.3, 0]);
const hintArrow = new Arrow({ start: [2.7, -2.35, 0], end: [1.45, -2.75, 0], color: YELLOW });
await scene.play(new AnimationGroup([new FadeIn(hint), new FadeIn(hintArrow)]));

// ---------- Helpers ----------
function normalCDF(x) {
  const t = 1 / (1 + 0.2316419 * Math.abs(x));
  const d = Math.exp(-x * x / 2) / Math.sqrt(2 * Math.PI);
  const p = 1 - d * t * (0.319381530 + t * (-0.356563782 + t * (1.781477937 + t * (-1.821255978 + t * 1.330274429))));
  return x >= 0 ? p : 1 - p;
}
function areaWithin(kk) { return (normalCDF(kk) - normalCDF(-kk)) * 100; }

const x0 = ax.c2p(0, 0)[0];
const xUnit = ax.c2p(1, 0)[0] - x0;
const y0 = ax.c2p(0, 0)[1];

function updateProbe() {
  const kk = Math.max(k, 0.02);
  scene.remove(probeArea);
  probeArea = ax.getArea(curve, [-kk, kk], { color: ORANGE, opacity: 0.45 });
  scene.add(probeArea);
  segL.setVertices([ax.c2p(-kk, 0), ax.c2p(-kk, pdf(kk))]);
  segR.setVertices([ax.c2p(kk, 0), ax.c2p(kk, pdf(kk))]);
  scene.remove(segL); scene.add(segL);
  scene.remove(segR); scene.add(segR);
  scene.remove(dotK); scene.add(dotK);
  const pPos = pctText.getCenter();
  scene.remove(pctText);
  pctText = new Text({ text: areaWithin(k).toFixed(2) + '%', color: ORANGE, fontSize: 30 });
  pctText.moveTo(pPos);
  scene.add(pctText);
  const kPos = kText.getCenter();
  scene.remove(kText);
  kText = new Text({ text: 'k = ' + k.toFixed(2), color: WHITE, fontSize: 20 });
  kText.moveTo(kPos);
  scene.add(kText);
}

function setK(v) {
  k = v;
  dotK.moveTo(ax.c2p(v, 0));
  updateProbe();
}

makeDraggable(dotK, scene, {
  constrainX: [ax.c2p(-3.4, 0)[0], ax.c2p(3.4, 0)[0]],
  constrainY: [y0, y0],
  onDrag: function (mob) {
    const cx = mob.getCenter()[0];
    k = Math.min(3.4, Math.abs(cx - x0) / xUnit);
    updateProbe();
  }
});

// ---------- Controls ----------
const controls = new Controls(scene, { position: 'top-right', width: 190 });
controls.addButton({ label: 'k = 1σ', onClick: function () { setK(1); } });
controls.addButton({ label: 'k = 2σ', onClick: function () { setK(2); } });
controls.addButton({ label: 'k = 3σ', onClick: function () { setK(3); } });

const bandMobs = [
  { mob: area3, base: 0.30 },
  { mob: area2, base: 0.40 },
  { mob: area1, base: 0.55 },
  { mob: lbl68, base: 1 },
  { mob: lbl95, base: 1 },
  { mob: lbl997, base: 1 }
];
for (const ln of sepLines) bandMobs.push({ mob: ln, base: 0.35 });
controls.addCheckbox({ label: 'Show bands', checked: true, onChange: function (c) {
  for (const b of bandMobs) b.mob.setOpacity(c ? b.base : 0);
}});

await scene.wait(999999);" }

